'use client';

/* SloshGauge — 复刻自 reactbits.dev (MIT + Commons Clause 参考重写)：弹簧-阻尼液位仪表
 * 液面跟随目标值做物理晃动（黏度/倾斜/溅射可調），可拖拽/键盘交互，零动画库依赖 */
import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { resolveToken } from '../../design/tokens';
import './SloshGauge.css';

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
const H = 1 / 120;
const DT_MAX = 0.05;
const TILT_GAIN = 0.07;
const TILT_MAX = 30;
const REST_POS = 0.05;
const REST_VEL = 2;
const STEP = 2;
const BIG = 10;
const BAND = 10;

const onColor = (hex: string) => {
  const raw = hex.replace('#', '');
  const full = raw.length === 3 ? [...raw].map(c => c + c).join('') : raw;
  const n = parseInt(full, 16);
  if (Number.isNaN(n)) return '#ffffff';
  return (((n >> 16) & 255) * 299 + ((n >> 8) & 255) * 587 + (n & 255) * 114) / 1000 >= 150 ? '#111111' : '#ffffff';
};

export interface SloshGaugeProps {
  /** 受控值 0-100；不传则用 defaultValue 非受控 */
  value?: number;
  defaultValue?: number;
  onChange?: (n: number) => void;
  interactive?: boolean;
  showValue?: boolean;
  disabled?: boolean;
  /** 'auto' 跟随品牌主色 */
  liquidColor?: string;
  /** 'auto' 跟随浮层底色 */
  glassColor?: string;
  width?: number;
  height?: number;
  radius?: number;
  ticks?: number;
  /** 0-1：越大越黏稠、晃动衰减越快 */
  viscosity?: number;
  /** 0-1：晃动时液面倾斜幅度 */
  tilt?: number;
  /** 0-1：撞到上下边缘的反弹能量 */
  splash?: number;
  unit?: string;
  ariaLabel?: string;
  className?: string;
}

export default function SloshGauge({
  value,
  defaultValue = 60,
  onChange,
  interactive = true,
  showValue = true,
  disabled = false,
  liquidColor = 'auto',
  glassColor = 'auto',
  width = 88,
  height = 180,
  radius = 20,
  ticks = 4,
  viscosity = 0.15,
  tilt = 0.45,
  splash = 0.42,
  unit = '%',
  ariaLabel = 'Level',
  className = ''
}: SloshGaugeProps) {
  const resolvedLiquid = liquidColor === 'auto' ? resolveToken('--color-primary', '#a9fd1c') : liquidColor;
  const resolvedGlass = glassColor === 'auto' ? resolveToken('--color-bg-elevated', '#252525') : glassColor;

  const root = useRef<HTMLDivElement>(null);
  const liquid = useRef<HTMLDivElement>(null);
  const marker = useRef<HTMLDivElement>(null);
  const textA = useRef<HTMLSpanElement>(null);
  const textB = useRef<HTMLSpanElement>(null);
  const start = clamp(value ?? defaultValue, 0, 100);
  const sim = useRef<any>({ x: start, v: 0, L: start, raf: 0, last: 0 });
  const grip = useRef<any>(null);
  const reduce = useRef(false);
  const [held, setHeld] = useState(false);
  const live = useRef<any>({});
  live.current = { viscosity, tilt, splash, width, height, value, onChange, unit };

  const paint = () => {
    const { x, v, L } = sim.current;
    const { tilt: t, width: W, height: Hh } = live.current;
    if (!Number.isFinite(x) || !Number.isFinite(L)) return; // 无效值不写入 clip-path（写入会被浏览器静默丢弃导致视觉冻死）
    const th = reduce.current ? 0 : clamp(t * v * TILT_GAIN, -TILT_MAX, TILT_MAX);
    const lean = (Math.tan((th * Math.PI) / 180) * W) / 2;
    const top = 100 - x;
    if (liquid.current) {
      liquid.current.style.clipPath = `polygon(0 calc(${top}% + ${lean}px), 100% calc(${top}% - ${lean}px), 100% 100%, 0 100%)`;
    }
    if (marker.current) marker.current.style.transform = `translateY(${((100 - L) * Hh) / 100}px)`;
  };

  const say = () => {
    const n = Math.round(sim.current.L);
    const s = `${n}${live.current.unit}`;
    root.current?.setAttribute('aria-valuenow', String(n));
    if (textA.current) textA.current.textContent = s;
    if (textB.current) textB.current.textContent = s;
  };

  const tick = (now: number) => {
    const s = sim.current;
    const { viscosity: vis, splash: give } = live.current;
    const rawDt = s.last ? (now - s.last) / 1000 : H;
    const dt = Number.isFinite(rawDt) && rawDt > 0 ? Math.min(rawDt, DT_MAX) : H;
    s.last = now;
    if (!Number.isFinite(vis) || vis <= 0) {
      s.x = s.L;
      s.v = 0;
    } else {
      const k = 1224 - 1044 * vis;
      const zeta = reduce.current ? 1 : 0.26 - 0.17 * vis;
      const c = 2 * zeta * Math.sqrt(k);
      const rest = reduce.current ? 0 : give;
      for (let n = Math.ceil(dt / H), h = dt / n; n > 0; n -= 1) {
        s.v = s.v * Math.exp(-c * h) + k * (s.L - s.x) * h;
        s.x += s.v * h;
        if (s.x > 100) { s.x = 100; s.v = -s.v * rest; }
        else if (s.x < 0) { s.x = 0; s.v = -s.v * rest; }
      }
      // 自愈：任何 NaN/Infinity 污染（参数异常等）立即回落到目标值，避免液面冻死
      if (!Number.isFinite(s.x) || !Number.isFinite(s.v)) { s.x = s.L; s.v = 0; }
      if (!grip.current && Math.abs(s.L - s.x) < REST_POS && Math.abs(s.v) < REST_VEL) {
        s.x = s.L;
        s.v = 0;
      }
    }
    paint();
    const parked = !grip.current && s.x === s.L && s.v === 0;
    if (parked) { s.raf = 0; s.last = 0; }
    else s.raf = requestAnimationFrame(tick);
  };
  const wake = () => {
    // 自愈：先取消旧帧再排新帧，杜绝“残留 raf id 非零 → wake 永久空转”的死循环
    cancelAnimationFrame(sim.current.raf);
    sim.current.raf = requestAnimationFrame(tick);
  };
  const setLevel = (L: number, instant?: boolean) => {
    const s = sim.current;
    s.L = clamp(L, 0, 100);
    if (instant) { s.x = s.L; s.v = 0; }
    say();
    wake();
  };

  useLayoutEffect(() => {
    if (value === undefined) return;
    if (grip.current && Math.round(sim.current.L) === value) return;
    setLevel(value, false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  useLayoutEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const sync = () => { reduce.current = mq.matches; };
    sync();
    mq.addEventListener('change', sync);
    say();
    paint();
    const s = sim.current;
    return () => { mq.removeEventListener('change', sync); cancelAnimationFrame(s.raf); s.raf = 0; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => { paint(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [width, height, tilt, showValue, interactive, disabled]);

  const levelAt = (clientY: number, g: any) =>
    clamp(((g.rect.bottom - clientY) / g.scale / (root.current?.offsetHeight || g.rect.height)) * 100, 0, 100);
  const report = () => {
    const g = grip.current;
    const n = Math.round(sim.current.L);
    if (g && n !== g.sent) { g.sent = n; live.current.onChange?.(n); }
  };

  const down = (e: React.PointerEvent) => {
    if (!interactive || disabled || grip.current || e.button !== 0) return;
    const el = root.current!;
    const rect = el.getBoundingClientRect();
    const scale = rect.height / (el.offsetHeight || rect.height) || 1;
    const markerY = rect.top + ((100 - sim.current.L) / 100) * rect.height;
    const g = {
      id: e.pointerId, rect, scale,
      band: Math.abs(e.clientY - markerY) <= BAND * scale,
      grab: null as number | null,
      at: sim.current.L, sent: NaN
    };
    grip.current = g;
    try { el.setPointerCapture(e.pointerId); } catch { /* noop */ }
    setHeld(true);
    if (g.band) wake();
    else { setLevel(levelAt(e.clientY, g)); report(); }
  };
  const move = (e: React.PointerEvent) => {
    const g = grip.current;
    if (!g || g.id !== e.pointerId) return;
    const at = levelAt(e.clientY, g);
    if (g.band && g.grab === null) { g.grab = sim.current.L - at; return; }
    setLevel(at + (g.grab ?? 0));
    report();
  };
  const up = (e: { pointerId: number }, reason?: string) => {
    const g = grip.current;
    if (!g || g.id !== e.pointerId) return;
    grip.current = null;
    try { root.current?.releasePointerCapture(e.pointerId); } catch { /* noop */ }
    setHeld(false);
    if (reason === 'escape') {
      setLevel(g.at);
      live.current.onChange?.(Math.round(g.at));
    } else if (live.current.value !== undefined && Math.round(sim.current.L) !== live.current.value) {
      setLevel(live.current.value);
    }
    wake();
  };
  const key = (e: React.KeyboardEvent) => {
    if (!interactive || disabled) return;
    if (e.key === 'Escape') { if (grip.current) up({ pointerId: grip.current.id }, 'escape'); return; }
    const L = sim.current.L;
    const d = e.shiftKey ? BIG : STEP;
    const next = ({
      ArrowUp: L + d, ArrowRight: L + d, ArrowDown: L - d, ArrowLeft: L - d,
      PageUp: L + BIG, PageDown: L - BIG, Home: 0, End: 100
    } as Record<string, number | undefined>)[e.key];
    if (next === undefined) return;
    e.preventDefault();
    setLevel(next, true);
    live.current.onChange?.(Math.round(sim.current.L));
  };

  const r = Math.min(radius, width / 2, height / 2);
  const label = `${Math.round(start)}${unit}`;

  return (
    <div
      ref={root}
      className={`slosh-gauge${className ? ` ${className}` : ''}`}
      role={interactive ? 'slider' : 'meter'}
      tabIndex={interactive && !disabled ? 0 : undefined}
      aria-label={ariaLabel}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(start)}
      aria-orientation={interactive ? 'vertical' : undefined}
      aria-disabled={disabled || undefined}
      data-interactive={interactive ? 'true' : 'false'}
      data-held={held ? 'true' : 'false'}
      data-disabled={disabled ? 'true' : 'false'}
      style={{
        '--sg-w': `${width}px`,
        '--sg-h': `${height}px`,
        '--sg-r': `${r}px`,
        '--sg-glass': resolvedGlass,
        '--sg-liquid': resolvedLiquid,
        '--sg-on-liquid': onColor(resolvedLiquid),
        '--sg-ticks': ticks,
        '--sg-font': `${clamp(Math.round(width * 0.16), 12, 20)}px`
      } as React.CSSProperties}
      onPointerDown={down}
      onPointerMove={move}
      onPointerUp={e => up(e)}
      onPointerCancel={e => up(e, 'cancel')}
      onLostPointerCapture={e => up(e, 'cancel')}
      onKeyDown={key}
    >
      {showValue ? <span ref={textA} className="slosh-gauge__value" aria-hidden="true">{label}</span> : null}
      <div ref={liquid} className="slosh-gauge__liquid" aria-hidden="true">
        {showValue ? <span ref={textB} className="slosh-gauge__value">{label}</span> : null}
      </div>
      {ticks > 0 ? <div className="slosh-gauge__ticks" aria-hidden="true" /> : null}
      {interactive && !disabled ? <div ref={marker} className="slosh-gauge__marker" aria-hidden="true" /> : null}
    </div>
  );
}

.slosh-gauge {
  --sg-w: 88px;
  --sg-h: 180px;
  --sg-r: 20px;
  --sg-glass: #27272a;
  --sg-liquid: #f5f5f5;
  --sg-on-liquid: #111111;
  --sg-ticks: 4;
  --sg-font: 14px;

  position: relative;
  display: inline-block;
  box-sizing: border-box;
  width: var(--sg-w);
  height: var(--sg-h);
  border-radius: var(--sg-r);
  overflow: clip;
  isolation: isolate;
  background: var(--sg-glass);
  font-size: var(--sg-font);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.slosh-gauge[data-interactive='true'] {
  cursor: ns-resize;
  touch-action: none;
  -webkit-touch-callout: none;
}

.slosh-gauge[data-disabled='true'] {
  opacity: 0.5;
  cursor: not-allowed;
}

.slosh-gauge__value {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: color-mix(in srgb, currentColor 65%, transparent);
  pointer-events: none;
}

.slosh-gauge__liquid {
  position: absolute;
  inset: 0;
  background: var(--sg-liquid);
  clip-path: polygon(0 100%, 100% 100%, 100% 100%, 0 100%);
}

.slosh-gauge__liquid .slosh-gauge__value {
  color: var(--sg-on-liquid);
}

.slosh-gauge__ticks {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 22%;
  height: 100%;
  background-image: linear-gradient(to top, color-mix(in srgb, currentColor 22%, transparent) 0 1px, transparent 1px);
  background-size: 100% calc(100% / var(--sg-ticks));
  background-repeat: repeat-y;
  background-position: bottom;
  pointer-events: none;
}

.slosh-gauge__marker {
  position: absolute;
  top: 0;
  right: 10%;
  left: 10%;
  height: 2px;
  margin-top: -1px;
  border-radius: 1px;
  background: currentColor;
  opacity: 0;
  transition: opacity 150ms ease;
  pointer-events: none;
}

.slosh-gauge[data-held='true'] .slosh-gauge__marker {
  opacity: 1;
}
